"""Reproducible, source-preserving coaching completion of the 57 open recipes.

Run from the repository root. Numerical choices below are onFlows coaching
defaults, not conversions of power into speed or claims of source equivalence.
"""
from copy import deepcopy
import json
from pathlib import Path

PATH = Path(__file__).resolve().parents[1] / "biathlon/data/training_method_library.json"
ALL = ["Run", "NordicSki", "RollerSki"]
V5 = {"type": "V5"}
CV = {"type": "CV"}
V6 = {"type": "V6"}


def race(distance):
    return {"type": "RACE_DISTANCE", "distance_m": distance}


def vt(seconds):
    return {"type": "V_DURATION", "duration_seconds": seconds}


def pair(value):
    return list(value) if isinstance(value, (list, tuple)) else [value, value]


def part(amount, anchor=V5, intensity=1., unit="seconds", **extra):
    return {"kind": "WORK", "work": {"unit": unit, "range": pair(amount)},
            "anchor": deepcopy(anchor), "speed_multiplier": pair(intensity), **extra}


def intervals(amount, anchor=V5, intensity=1., *, unit="seconds", reps=(1, 5), rest=180,
              rest_type="ACTIVE_Z1", pattern=None, **extra):
    p = {"structure": "COMPOUND" if pattern else "INTERVALS", "anchor": deepcopy(anchor),
         "speed_multiplier": pair(intensity), "repetitions": list(reps),
         "recovery": {"seconds": pair(rest), "type": rest_type}, **extra}
    if pattern:
        p["pattern"] = pattern
    else:
        p["work"] = {"unit": unit, "range": pair(amount)}
    return p


def long_run(pattern, minimum_scale=.5):
    return intervals(0, pattern=pattern, reps=(1, 1), rest=0,
                     structure="PROGRESSIVE_CONTINUOUS", minimum_scale=minimum_scale,
                     includes_preparation=True)


def build(data):
    rows = [r for r in data["methods"] if r.get("completion_version") != 1]
    by_id = {r["id"]: r for r in rows}
    completed = {}

    def add(source, title, prescription, execution, decision, *, purpose=None, rest=None,
            success=None, errors=None, progression=None, short=None, sports=None, suffix="",
            terrain=False, continuous=False):
        original = by_id[source]
        identifier = "OF-" + source + suffix
        default_progression = ("Първо запази еднакъв ритъм и техника. Удължаване на отсечката се отключва след две потвърдени съпоставими изпълнения с RPE ≤ 8; календарът сам не увеличава дозата. "
                               "При по-дългата отсечка използвай долната част на скоростния диапазон. Броят остава ограничен от седмичния бюджет.")
        p = deepcopy(prescription)
        if terrain:
            p["execution_control"] = "EFFORT_ON_TERRAIN"
            execution += " По наклона водещи са времето, усилието и техниката. Показаната скорост е равнинен еквивалент за модела, а не цел за GPS."
        r = {"id": identifier, "title": title + " · адаптация onFlows", "sports": sports or original["sports"],
             "disciplines": deepcopy(original.get("disciplines", [])), "periods": deepcopy(original["periods"]),
             "source": {**deepcopy(original["source"]), "evidence": "EXPLICIT_ONFLOWS_COACH_ADAPTATION_NOT_SOURCE_EQUIVALENT"},
             "original": {k: deepcopy(v) for k, v in original["original"].items() if k != "structured"},
             "adaptation": {"classification": "Изпълнима треньорска адаптация; не е еквивалент на публикувания протокол",
                            "notes": decision, "zone_note": "Зоните и Tmax се изчисляват по текущата крива за същото средство. Пулсът е отделен индивидуален ориентир, не преобразуване от процента скорост."},
             "derived_from": [source], "is_source_equivalent": False, "completion_version": 1,
             "automatic_selection": True, "prescription": p,
             "guidance": {"purpose": purpose or "Усвояване и задържане на зададения ритъм чрез структурата по-долу. Дозата следва индивидуалната устойчивост, целта на седмицата и възстановяването.",
                          "execution": execution,
                          "recovery": rest or "Изпълни показаната почивка изцяло. Активната почивка е леко движение без допълнителен бърз акцент; пасивната означава спиране. След последното повторение премини към отпускането.",
                          "success": success or "Последната отсечка запазва предписания ритъм и техниката на първата. Завърши с резерв, обикновено при RPE не повече от 8/10; това не е тест до отказ.",
                          "errors": errors or "Прекалено бърз старт, скъсяване на почивката или добавяне на повторения, за да се достигне пулс. Не събирай максималната скорост, най-дългата отсечка и най-големия брой наведнъж.",
                          "adjustment": "Ако темпото или техниката се разпадат, прекрати бързата работа и запиши реалното изпълнение. Не компенсирай с по-къса почивка. Следващата доза се съобразява с Recovery, потвърденото изпълнение и оставащия бюджет.",
                          "progression": progression or default_progression}}
        if short:
            r["requirements"] = {"short_test_max_seconds": short}
            r["guidance"]["execution"] += f" Нужен е приет реален максимален тест с продължителност до {short} сек за същото средство; V5 сама не е достатъчна за този кратък край."
        variable = any(s.get("work", {}).get("range", [0, 0])[0] != s.get("work", {}).get("range", [0, 0])[1]
                       for s in p.get("pattern", [p]))
        if variable:
            r["progression"] = {"kind": "WITHIN_RANGE", "group": identifier, "steps": 3, "stage": None}
        elif not progression:
            r["guidance"]["progression"] = "Запази зададената структура и почивки. Седмичният план избира броя цели повторения или мащаба на целия пробег според Recovery, тренировъчната цел и наличния бюджет. Скоростите се преизчисляват при обновяване на личната крива; не се увеличават автоматично с приближаването на старта."
        if continuous:
            r["guidance"]["adjustment"] += " Всички части се съкращават пропорционално; не се отрязва състезателният блок."
        rows.append(r)
        completed.setdefault(source, []).append(identifier)
        return r

    # Severe-domain running: finite coach endpoints replace exhaustion tests.
    add("R06", "200 m с контролирана висока скорост", intervals(200, race(200), (.9, .95), unit="meters", reps=(2, 8), rest=180, rest_type="WALK"),
        "Изпълни 200 m бързо, но с резерв, без максимално ускоряване в началото.",
        "150% КС от оригинала е заменено с 90–95% от актуална V200; това е нова скоростна задача.", short=60)
    p = intervals((.65, .7), CV, 1.4, unit="capacity_fraction", reps=(1, 4), rest=0)
    p["recovery"].update(work_ratio=[2, 2], anchor=CV, speed_multiplier=[.7, .7])
    add("R08", "Кратки интервали при 140% КС с лична продължителност", p,
        "Работи при 140% от индивидуалната КС. Времето е 65–70% от Tmax при тази скорост, а не фиксирани секунди за всички.",
        "Оригиналната формула с D′ е заменена с 0.65–0.70 × Tmax от текущата крива. Не се изчислява или приписва измерен D′.", short=120,
        rest="Почивката е два пъти личното работно време, активно при 70% КС. Запази тази продължителност и скорост.")
    add("R09", "90 сек по индивидуалната кратка устойчивост", intervals(90, vt(90/.7), (.97, 1.), reps=(1, 4), rest=180),
        "Изпълни 90 секунди при 97–100% от скоростта, която текущата крива поддържа около 129 секунди.",
        "CS + 0.7D′/90 е заменено с независима V(90/0.7). Общото време и почивката са запазени; D′ не се предполага.", short=120)
    p = intervals((.2, .25), V5, (.95, 1.), unit="capacity_fraction", reps=(2, 6), rest=0, rest_type="PASSIVE")
    p["recovery"]["work_ratio"] = [2/3, 2/3]
    add("R13", "Интервали 20–25% от Tmax по V5", p,
        "Всяко повторение заема 20–25% от личното Tmax при избраната скорост. Поддържай равномерно усилие и приключи преди отказ.",
        "90% PTV е заменено с отделна 95–100% V5 рецепта. Пределният RPE критерий е заменен с ограничен брой и контрол на качеството.",
        rest="Пасивна почивка, равна на две трети от личното работно време. Показаните секунди се преизчисляват заедно с работата.")
    seq = [part(s, V6, recovery_after_seconds=r, recovery_after_type="ACTIVE_Z1") for s, r in zip([180,120,60,45,30], [120,80,40,30,20])]
    add("R18", "Намаляващи интервали 180→30 сек по V6", intervals(0, V6, pattern=seq, reps=(1,1), rest=0,
        structure="SEQUENCE", tail=part(30, V6, recovery_after_seconds=20), tail_repetitions=[0,12]),
        "Следвай реда 180, 120, 60, 45 и 30 сек при V6. След това програмата може да добави само цели 30-секундни повторения, без да повтаря дългото начало.",
        "Съхранен е намаляващият ред. Работата до отказ е заменена с максимум 12 допълнителни повторения и индивидуален бюджет; почивката е леко движение вместо фиксирани 66% КС.",
        rest="Между началните отсечки: 120, 80, 40, 30 и после 20 сек леко движение. Между допълнителните 30-секундни повторения: 20 сек.")

    # Ski adaptations: preserve timing; select speed anchors independently.
    add("S01", "Ски 3 мин по V6", intervals(180, V6, (.9,.95), reps=(1,6), rest=90),
        "Три минути устойчив ски ритъм със запазена техника. Използвай кривата за действителното средство и съпоставими условия.",
        "85% P6 на ергометър не се превръща в процент скорост. Избрани са отделно 90–95% V6 и активна 90-секундна почивка.")
    add("S02", "Ски постоянни 5 мин по V5", intervals(300, V5, .9, reps=(1,5)),
        "Пет минути равномерно при 90% V5; не ускорявай, за да достигнеш пулс в началото.",
        "МАС се приближава с договорената V5. Пътечката с 9% наклон и фиксираната скорост в почивката са заменени с полево изпълнение и 3 мин леко движение.")
    add("S03", "Ски 90 сек бързо + 210 сек устойчиво", intervals(0, pattern=[part(90,V5),part(210,V5,.85)], reps=(1,5)),
        "Първите 90 секунди са при V5, следващите 210 при 85% V5 без междинно спиране. Бързото начало не е максимален спринт.",
        "Запазени са времето и процентите от МАС с V5 като оценка. Външната почивка е 3 мин леко движение; не се възпроизвежда лабораторният наклон.")
    for source, pattern, title, execution in [
        ("S04", [part(120,V5,(.95,1)),part(180,CV,(.95,1))], "Ски 2 мин по V5 + 3 мин около КС", "Две минути при 95–100% V5, после три минути при 95–100% КС. И двете части са работа."),
        ("S05", [s for _ in range(3) for s in [part(40,V5,(.95,1)),part(60,CV,(.95,1))]], "Ски 3 × (40 сек V5 + 60 сек КС)", "В един петминутен блок редувай три пъти 40 сек по V5 и 60 сек около КС. По-ниската скорост остава работна част.")]:
        add(source,title,intervals(0,pattern=pattern,reps=(1,5)),execution,
            "Лактатно определената ниска скорост е заменена с отделен диапазон 95–100% КС. Не се приема, че КС е скоростта при 4 mmol/L. Почивка: 3 мин активно.")
    add("S06", "Ски 40/20 сек по V5", intervals(0,pattern=[part(20,CV,.6,kind="RECOVERY"),part(40,V5,(1,1.05))],reps=(3,12),rest=0),
        "Всеки цикъл започва с 20 сек леко движение при 60% КС и продължава с 40 сек при 100–105% V5. Изпълни само показания брой; не продължавай до отказ.",
        "Запазено е времето 20 сек облекчение → 40 сек работа. 120% MAP и 60% MAP не са преобразувани; V5/КС и 3–12 цикъла са независими избори на onFlows. Erratum 10.1123/ijspp.2023-0347 е идентифициран, но пълният му текст не е достъпен за проверка.",
        purpose="Натрупване на кратка аеробна работа при запазена ски техника. Леките 20 секунди позволяват повторяеми 40-секундни усилия.",
        rest="20 секунди активно при 60% КС в началото на всеки цикъл. Няма допълнителна почивка след всяка 40-секундна част.")
    add("XC07", "Ски фартлек 2 мин устойчиво / 1 мин по-леко", intervals(0,CV,pattern=[part(120,CV,(.98,1.02)),part(60,CV,.8)],reps=(3,10),rest=0),
        "Редувай 2 мин силно, но контролирано усилие (RPE 7–8) и 1 мин по-леко (RPE 4–5), съобразено с релефа.",
        "Пулсовият фартлек е конкретизиран като 2/1 мин. КС е отделна скоростна опора; процент от пулса не е преобразуван в процент КС.",terrain=True)
    add("XC10", "Ски контролирани ускорения 20–30 сек", intervals((20,30),vt(30),(.93,.97),reps=(2,8),rest=240,rest_type="WALK"),
        "Ускори плавно и запази технически качествена скорост. При удължаване към 30 сек намалява относителният процент.",
        "Максималните спринтове са заменени с 93–97% V30 и пълна 4-минутна почивка; това е контролирана бързина, не измерен максимум.",short=30)
    add("XC11", "Ски състезателен ритъм 5–15 мин", intervals((300,900),{"type":"PRIMARY_RACE"},(.95,1.02),reps=(1,1),rest=0,structure="CONTINUOUS"),
        "Работи по състезателно трасе с RPE 7–8. Започни с 5 мин усвояване на ритъма; достигни 15 мин само след потвърдена поносимост.",
        "Пулсовият пример е заменен с текущата скорост за основната дисциплина и прогресия 5–15 мин. Скоростта служи за сравнение; релефът определя моментното усилие.",terrain=True)
    add("XC12", "Ски пирамида около КС", intervals(0,CV,pattern=[part(n*60,CV,(.95,1),recovery_after_seconds=120) for n in [5,6,7,8,7,6,5]],
        reps=(1,1),rest=0,structure="SCALED_SEQUENCE",minimum_scale=.4),
        "Следвай седемте части на пирамидата. В началния вариант всички работни времена са съкратени пропорционално; 5–6–7–8–7–6–5 мин е горна граница, а не задължителна доза.",
        "Избрани са 95–100% КС, 2 мин активна почивка и 40–100% от пълната пирамида. Това конкретизира качественото предписание независимо от оригиналните пулсови проценти.")

    add("MD12", "400 m състезателно + 2 × 100 m ускоряване", intervals(0,race(1500),pattern=[part(400,race(1500),unit="meters"),part(100,race(1500),1.02,unit="meters"),part(100,race(1500),1.04,unit="meters")],reps=(1,4),rest=360,rest_type="WALK"),
        "400 m на актуална V1500, последвани без спиране от два отрязъка по 100 m с леко ускоряване. Не превръщай финала в максимален спринт.",
        "Качественото финално ускорение е уточнено като 102% и 104% V1500; процентите и 6-минутната почивка са треньорски избор.")
    add("RD06", "Дълги аеробни повторения 2000 m", intervals(2000,V5,.9,unit="meters",reps=(1,3),rest=240),
        "2000 m при 90% V5 с равномерен ритъм. Краткият партньор е отделна рецепта OF-RD06-FAST.",
        "Двата независими акцента са разделени. Комбинират се само по правилото за недостиг на тренировъчни слотове, с 50% от собствения бюджет на всеки.",suffix="-LONG")
    add("RD06", "Кратки аеробни повторения 300 m", intervals(300,V5,(1.1,1.15),unit="meters",reps=(2,12),rest=90),
        "300 m при 110–115% V5 с контролирана техника. Дългият партньор е отделна рецепта OF-RD06-LONG.",
        "Избран е по-умерен диапазон от елитния пример. Партньорите имат собствени бюджети; не се залепват две пълни дози.",suffix="-FAST")
    for source, maximum in [("RD07",10),("RD08",4),("RD09",15)]:
        p=deepcopy(by_id[source]["prescription"])
        p["repetitions"]=[1,maximum]
        add(source,by_id[source]["title"],p,"Следвай показаните отсечки по актуалната Vмаратон. Темпото е от днешната крива; не преследвай абсолютните времена на елитния пример.",
            "Относителните диапазони са съзнателно избрани треньорски ориентири, вдъхновени от елитния пример. Те не доказват еднакъв физиологичен ефект. Броят е ограничен от личния седмичен бюджет.")
    add("RD10", "Прогресивен пробег 45–90 мин",long_run([part(n*90,race(42195),f) for n,f in [(20,.84),(16,.86),(10,.88),(8,.9),(4,.92),(2,.94)]]),
        "Премини плавно през шестте скорости без почивка. Продължителността на всяка част се намалява с един и същ коефициент, за да се запази развитието на пробега.",
        "30 km е заменено с 45–90 мин. Скоростите са изрично избрана постепенна стълбица по текущата Vмаратон, без копиране на елитния километраж.",continuous=True)

    # Anderson: remove qualitative gaps while preserving the published text.
    add("AO05","60 сек контролирано бързо",intervals(60,vt(60),(.9,.95),reps=(2,6),rest=120),
        "Една минута бързо с резерв, следвана от две минути леко движение.","Почти максимално е конкретизирано като 90–95% V60, с краен брой 2–6; не е тест до отказ.",short=90)
    p=intervals(200,race(400),unit="meters",reps=(2,8),rest=240,rest_type="WALK",pace_offset={"distance_m":200,"seconds":[-1,-1]})
    add("AO06","200 m по времето на 400 m минус 1 сек",p,
        "Времето за 200 m е половината от актуалното прогнозно време за 400 m минус една секунда. Запази отпусната техника и пълната почивка.",
        "Точната времева корекция е запазена. Опората е актуална V400; броят и 4-минутната почивка са ограничени треньорски настройки.",short=90)
    fast_combinations=[
        ("AO08","200 m бързо + 400 m V800",[(200,200,.93),(400,800,1)],60),
        ("AO15","400 m бързо + 800 m V3000",[(400,400,.93),(800,3000,1)],90),
        ("AO20","600 m бързо + 1000 m V5000",[(600,600,.93),(1000,5000,1)],120),
        ("AO25","200 / 600 / 1600 m със смяна на ритъма",[(200,200,.93),(600,1500,.95),(1600,10000,1)],60),
    ]
    for source,title,phases,short in fast_combinations:
        pattern=[part(d,race(a),f,unit="meters") for d,a,f in phases]
        add(source,title,intervals(0,pattern=pattern,reps=(1,3),rest=300,rest_type="WALK_OR_JOG"),
            "Изпълни свързаните отрязъци без междинно спиране, в реда от рецептата. Бързото начало е контролирано; при преминаване към състезателния ритъм възстанови координацията.",
            "Почти максималното начало е уточнено като 93% от скоростта за съответната кратка дистанция. Междинните качествени части са конкретизирани в рецептата; 5 мин почивка и 1–3 повторения са onFlows избор.",short=short)
    add("AO10","400 m по-бързо + 400–800 m V1500",intervals(0,race(1500),pattern=[part(400,race(1500),unit="meters",pace_offset={"distance_m":400,"seconds":[-4,-4]}),part((400,800),race(1500),unit="meters")],reps=(1,4),rest=240),
        "Първите 400 m са с 4 секунди по-бързи от текущото време за 400 m при V1500. Без спиране премини към 400 m при V1500; удължавай втората част към 600 и 800 m след успешно изпълнение.",
        "Запазена е точната корекция −4 сек/400 m, а не приблизителен процент. Избрани са текущата V1500 и 4 мин активна почивка.")
    add("AO11","1200 m контролирано + 400 m V1500",intervals(0,race(1500),pattern=[part(1200,race(1500),unit="meters",pace_offset={"distance_m":400,"seconds":[4,6]}),part(400,race(1500),unit="meters")],reps=(1,3),rest=300),
        "Първите 1200 m са с 4–6 сек по-бавно на всеки 400 m от текущата V1500. Последните 400 m са при актуалната V1500 без спиране.",
        "Запазена е времевата корекция в началото. Бъдещата целева скорост във финала е заменена с актуалната V1500; броят и почивката са треньорски избор.")
    add("AO13","Къси изкачвания 30–45 сек",intervals((30,45),race(1500),(.95,1),reps=(2,8),rest=180,rest_type="WALK"),
        "Избери умерено изкачване около 3–4%. Работи с RPE 7–8, стабилен таз и кратка крачка; върни се спокойно.",
        "200 m качествено нагоре е заменено с 30–45 сек; V1500 е само равнинна моделна опора, а водещо е усилието.",terrain=True)
    add("AO14","1200 m по V3000",intervals(1200,race(3000),unit="meters",reps=(1,3),rest=180),
        "Изпълни 1200 m на актуалната скорост за 3000 m. Не ускорявай последната обиколка за компенсация.","Конкретизирана е липсващата почивка: 3 мин активно. Изходният максимум е три повторения; седмичният бюджет може да намали броя.")
    for source,distance,intensity,count in [("AO17",800,(1,1.025),6),("AO18",400,(1.01,1.037),12)]:
        add(source,f"{distance} m около V5000",intervals(distance,race(5000),intensity,unit="meters",reps=(2,count),rest=90,rest_type="WALK_OR_JOG"),
            f"Поддържай равномерни {distance} m в показания диапазон около актуалната V5000. Започни спокойно и запази същия ритъм в края.",
            "Наблюдаваната средна скорост от изследването не е универсална норма. Тук тя е горна граница на изрично избран диапазон, с 90 сек ходене или леко бягане.")
    add("AO27","Триминутни изкачвания за ритъм на 10 km",intervals(180,race(10000),(.98,1.02),reps=(1,6),rest=120),
        "На умерен наклон около 3% поддържай RPE 7–8 за три минути. Не преследвай равнинното темпо на 10 km нагоре.",
        "V10km е моделна равнинна опора. Реалното изпълнение е по време и усилие; избрани са 2 мин активна почивка.",terrain=True)
    add("AO29","1000→2000 m по актуална V10km",intervals((1000,2000),race(10000),(1,1.02),unit="meters",reps=(1,4),rest=120),
        "Започни с 1000 m малко над състезателния ритъм и постепенно удължи към 2000 m при текущата V10km. Запази сходен общ обем при първото удължаване.",
        "Абсолютните времена за цел под 40 мин са заменени с актуална V10km. Избрани са 2 мин активна почивка и максимум четири повторения.")
    add("AO32","Продължително бягане с полумаратонски блок",long_run([part(1600*4,CV,.7,unit="meters"),part(1600*6,race(21097.5),unit="meters"),part(1600,CV,.7,unit="meters")]),
        "Лека начална част, плавно преминаване към актуалната Vполумаратон и лек финал. Всички части се съкращават заедно според бюджета.",
        "Целевата бъдеща скорост е заменена с текущата Vполумаратон. Мили са закръглени до 1600 m за работната версия; допуска се 50–100% от структурата.",continuous=True)
    add("AO34","400 / 800 / 2000 m състезателни ритми",intervals(0,pattern=[part(400,race(5000),unit="meters"),part(800,race(10000),unit="meters"),part(2000,race(21097.5),unit="meters")],reps=(1,2),rest=300),
        "400 m на V5000, веднага 800 m на V10km и 2000 m на актуална Vполумаратон. Избягвай резки максимални ускорения между частите.",
        "Печатна стр. 429 съдържа разминаване между заглавието 400–1200–3200 и подробната рецепта. Избрана е подробната рецепта 400–800–2000, с текущи състезателни скорости и 5 мин леко бягане.")
    add("AO35","45–90 мин с маратонски блок",long_run([part(1800,CV,.7),part(2700,race(42195)),part(900,CV,.7)]),
        "Леко начало, равномерен блок на текущата Vмаратон и леко завършване. Дължините се съкращават пропорционално; не прескачай началната част.",
        "Пропорцията 2/3/1 от дистанционния пример е използвана за нова времева структура 30/45/15 мин като горна граница, мащабирана до 50–100%. Използва се актуална, а не пожелана маратонска скорост.",continuous=True)
    add("AO36","Съкратена маратонска репетиция",long_run([part(6400,race(42195),.85,unit="meters"),part(8000,race(42195),unit="meters"),part(1600,race(42195),.85,unit="meters")]),
        "Използвай познати обувки, хранене и терен. Леко начало, блок на актуална Vмаратон, лек финал. Това е репетиция на ритъма и организацията, не състезание.",
        "Оригиналният дълъг симулатор е заменен с по-къса структура 6.4/8/1.6 km, мащабирана до 50–100%. Това не е същата 21-милна сесия и не гарантира готовност за маратон.",continuous=True)
    add("AO37","Продължително контролирано изкачване",intervals((2400,3600),race(42195),(.98,1.03),reps=(1,1),rest=0,structure="CONTINUOUS",execution_control="EFFORT_ON_TERRAIN"),
        "На умерено изкачване или пътечка 2–5% поддържай RPE 6–7. Започни с 40 мин и удължавай само при стабилна техника и възстановяване.",
        "Елитният пример е заменен с 40–60 мин по усилие. Vмаратон служи само за равнинен еквивалент; не се задава постоянна GPS скорост нагоре.",terrain=True)

    # Mølmen–Rønnestad: separate speed recipes, never numerical power conversion.
    note = "Структурна адаптация от мощност към отделна скоростна задача: процентите са избрани от onFlows, не са преобразуване P5/P40/FTP/MAP → скорост. Обемът е ограничен от личния бюджет."
    add("MR01","Дълги интервали 5–8 мин по V5",intervals((300,480),V5,(.85,.95),reps=(1,5),rest=180),"По-късите петминутни части са по-бързи; при удължаване към осем минути намали процента. Запази устойчив ритъм.",note,sports=ALL)
    add("MR02","Прагова работа 8–15 мин около КС",intervals((480,900),CV,(.95,1),reps=(1,4),rest=120),"Удължавай от 8 към 15 мин около КС с контролирано усилие. Ниската скорост не е почивка.",note,sports=ALL)
    add("MR03","30/15 сек в серии по V5",intervals(30,V5,(1,1.05),reps=(4,13),rest=15,sets={"count":2,"recovery_seconds":180,"recovery_type":"ACTIVE_Z1"}),"Две серии от равномерни 30-секундни части; 15 сек леко движение между тях. Между сериите почини три минути.",note,sports=ALL)
    for src,base in [("MR04","S05"),("MR05","S04")]:
        ref=next(r for r in rows if r["id"]=="OF-"+base)
        add(src,ref["title"].replace("Ски ","").replace(" · адаптация onFlows",""),ref["prescription"],ref["guidance"]["execution"],note,sports=ALL)
    add("MR06","10/20 сек контролирано по V5",intervals(10,V5,(1.1,1.15),reps=(6,15),rest=20,rest_type="PASSIVE",sets={"count":2,"recovery_seconds":180,"recovery_type":"ACTIVE_Z1"}),"Десет секунди бързо, двадесет секунди пасивно. Това е кратък аеробен ритъм, не максимален спринт.",note,sports=ALL)
    for src,base_seconds,anchor,intensity in [("MR07",360,V5,.9),("MR08",600,CV,.98)]:
        pattern=[s for _ in range(3) for s in [part(5,vt(15),.9),part(base_seconds/3-5,anchor,intensity)]]
        add(src,"Устойчив блок с три 5-секундни ускорения",intervals(0,pattern=pattern,reps=(1,4),rest=180),
            f"В {base_seconds//60}-минутния блок включи три кратки ускорения, равномерно разпределени. Всяко заема пет секунди от блока; не се добавя към времето.",note+" Избрани са три контролирани ускорения при 90% V15.",sports=ALL,short=30)
    for src,pattern,title in [
        ("MR09",[part(5,vt(15),.9),part(25,V5,1)],"30/15 сек с кратко бързо начало"),
        ("MR10",[part(5,vt(15),.9),part(35,V5),part(60,CV,.98),part(40,V5),part(60,CV,.98),part(40,V5),part(60,CV,.98)],"5 мин променлив ритъм с 5 сек ускорение"),
        ("MR11",[part(5,vt(15),.9),part(115,V5),part(180,CV,.98)],"2 + 3 мин с кратко ускорение в началото")]:
        add(src,title,intervals(0,pattern=pattern,reps=(2,10) if src=="MR09" else (1,4),rest=15 if src=="MR09" else 180),
            "Петте бързи секунди са вътре в първата работна част. След тях премини веднага към показания устойчив ритъм; не удължавай общия блок.",
            note+(" Бързият старт е във всяко повторение на тази отделна адаптация, вместо само в първите четири на оригинала." if src=="MR09" else " Ускорението е контролирано при 90% V15, не максимален спринт."),sports=ALL,short=30)
    for src,count in [("MR12",13),("MR13",12)]:
        add(src,f"30/15 сек · две серии до {count} повторения",intervals(30,V5,(1,1.05),reps=(4,count),rest=15,sets={"count":2,"recovery_seconds":180,"recovery_type":"ACTIVE_Z1"}),
            "Запази повторяеми 30 секунди работа и 15 секунди леко движение. Две серии, три минути между тях. Не копирай честотата на изследователския тренировъчен блок.",
            note+" Избрани са две серии и краен брой повторения. Високата седмична честота и работата при максимално повторяема мощност не са пренесени.",sports=ALL)
    add("MR14","8 мин редуване 60/60 около КС",intervals(0,pattern=[s for _ in range(4) for s in [part(60,CV,1.05),part(60,CV,.9)]],reps=(1,4),rest=180),
        "Четири пъти редувай една минута при 105% КС и една при 90% КС без спиране. Целият блок е осем минути, включително по-леките части.",note+" Пауза между блоковете: избрани 3 мин активно.",sports=ALL)
    pattern=[s for _ in range(10) for s in [part(30,V5,1),part(15,CV,.7)]]+[part(30,V5,1)]
    add("MR15","8 мин с вътрешни 30/15 сек",intervals(0,pattern=pattern,reps=(1,4),rest=180),
        "Десет цикъла 30 сек по V5 / 15 сек леко при 70% КС, после последни 30 сек по V5: точно осем минути. По-леките части са вътре в блока.",
        note+" Не се твърди изравнена средна мощност. Липсващото разпределение на последния частичен цикъл е решено изрично като 10 × 45 + 30 сек; почивката между блоковете е 3 мин.",sports=ALL)
    add("MR16","5 мин с три 30-секундни ускорения",intervals(0,pattern=[s for _ in range(3) for s in [part(30,V5),part(70,CV,.95)]],reps=(1,4),rest=180),
        "Три пъти редувай 30 сек при V5 и 70 сек при 95% КС. Всички части влизат в петминутния блок; по-ниската скорост остава работа.",note+" Избран е равномерен ред 3 × (30 + 70 сек) и 3 мин активна почивка.",sports=ALL)
    completed["MR17"]=["OF-MR-15","OF-MR-30","OF-MR-45"]
    for source,targets in completed.items():
        by_id[source]["related_method_ids"]=targets
        by_id[source]["implementation_status"]="WORKING_ADAPTATION_AVAILABLE"
        for target in targets:
            if target in by_id:
                by_id[target]["derived_from"]=[source]
    data["methods"]=rows
    data["version"]="onflows-training-method-library-v3-complete-recipes"
    data["updated_at"]="2026-10-12"
    data["completion_audit"]={"version":1,"source_count":len(completed),"source_to_working_methods":completed,
        "policy":"Sources unchanged; separate explicit coach adaptations; readiness, current-curve and weekly-budget gates retained."}
    data["counts"]={"total":len(rows),"with_prescription":sum(bool(r.get("prescription")) for r in rows),
                    "automatic":sum(bool(r.get("prescription")) and r.get("automatic_selection",False) for r in rows),
                    "reference_only":sum(not r.get("prescription") for r in rows)}
    assert len(completed)==57, len(completed)
    assert len({r["id"] for r in rows})==len(rows)
    return data


